import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class StringUnescaper {
    public static String unescapeJava(String str) throws Exception {
        if (str == null) {
            return null;
        }
        StringBuilder sb = new StringBuilder();
        Pattern p = Pattern.compile("\\\\(\\p{XDigit}{1,4}|.)");
        Matcher m = p.matcher(str);
        int lastMatchEnd = 0;
        while (m.find()) {
            sb.append(str, lastMatchEnd, m.start());
            String escape = m.group(1);
            if (escape.length() == 1) {
                char ch = escape.charAt(0);
                switch (ch) {
                    case 'b':
                        sb.append('\b');
                        break;
                    case 't':
                        sb.append('\t');
                        break;
                    case 'n':
                        sb.append('\n');
                        break;
                    case 'f':
                        sb.append('\f');
                        break;
                    case 'r':
                        sb.append('\r');
                        break;
                    case '"':
                        sb.append('"');
                        break;
                    case '\'':
                        sb.append('\'');
                        break;
                    case '\\':
                        sb.append('\\');
                        break;
                    default:
                        throw new Exception("Invalid escape sequence: \\" + ch);
                }
            } else {
                int code = Integer.parseInt(escape, 16);
                sb.append((char) code);
            }
            lastMatchEnd = m.end();
        }
        sb.append(str.substring(lastMatchEnd));
        return sb.toString();
    }

    public static void main(String[] args) {
        try {
            String escaped = "This is a test string with a newline: \\n and a tab: \\t";
            String unescaped = unescapeJava(escaped);
            System.out.println(unescaped);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

