protected <V, E> GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    DijkstraShortestPath<V, E> dijkstra = new DijkstraShortestPath<>(graph);
    V startVertex = null;
    V endVertex = null;

    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        if (startVertex == null) {
            startVertex = source;
        }
        if (!graph.containsEdge(startVertex, target)) {
            endVertex = target;
            break;
        }
        startVertex = target;
    }

    if (startVertex != null && endVertex != null) {
        return dijkstra.getPath(startVertex, endVertex);
    }

    return null;
}

