private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    StringBuilder output = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            if (i + 1 < input.length()) {
                char nextChar = input.charAt(i + 1);
                switch (nextChar) {
                    case 'n':
                        output.append('\n');
                        break;
                    case 't':
                        output.append('\t');
                        break;
                    case 'r':
                        output.append('\r');
                        break;
                    case '\\':
                        output.append('\\');
                        break;
                    default:
                        output.append(nextChar);
                        break;
                }
                i++; // Skip the next character as it's already processed
            } else {
                output.append('\\'); // If it's the last character, just append the backslash
            }
        } else {
            output.append(c);
        }
    }
    return output.toString();
}

